            customers = [i for i in range(n) if i != depot]
        elif demands is not None:
            if isinstance(demands, dict):
                customers = [k for k in demands.keys() if k != depot]
            else:
                customers = [i for i in range(len(demands)) if i != depot]
        elif coords is not None:
            customers = [i for i in range(len(coords)) if i != depot]
        elif dist is not None:
            customers = [i for i in range(len(dist)) if i != depot]
        else:
            customers = []
    else:
        customers = [c for c in list(customers) if c != depot]

    def demand_of(c):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return demands.get(c, 1)
        return demands[c]

    def euclid(a, b):
        ax, ay = coords[a]
        bx, by = coords[b]
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    def d(a, b):
        if dist is not None:
            return dist[a][b]
        return euclid(a, b)

    if capacity is None:
        cap = 10 ** 18
    else:
        cap = capacity

    remaining = set(customers)
    if not remaining:
        return []

    depot_d = {c: d(depot, c) for c in customers}

    def route_load(r):
        s = 0
        for c in r:
            s += demand_of(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        s = d(depot, r[0]) + d(r[-1], depot)
        for i in range(len(r) - 1):
            s += d(r[i], r[i + 1])
        return s

    def cheapest_insertion_seed():
        best = None
        best_key = None
        for c in remaining:
            if demand_of(c) > cap:
                key = (1, demand_of(c), depot_d[c], c)
            else:
                key = (0, depot_d[c], demand_of(c), c)
            if best_key is None or key < best_key:
                best_key = key
                best = c
        return best

    routes = []
    while remaining:
        seed = cheapest_insertion_seed()
        route = [seed]
        load = demand_of(seed)
        remaining.remove(seed)

        while True:
            feasible = [c for c in remaining if load + demand_of(c) <= cap]
            if not feasible:
                break
            last = route[-1]
            nxt = min(feasible, key=lambda c: (d(last, c) - 0.35 * depot_d[c], demand_of(c), c))
            route.append(nxt)
            load += demand_of(nxt)
            remaining.remove(nxt)
        routes.append(route)

    def two_opt_route(r):
        n = len(r)
        if n < 4:
            return r
        improved = True
        while improved:
            improved = False
            best_i = -1
            best_j = -1
            best_delta = 0.0
            for i in range(n - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j]
                    d2 = depot if j == n - 1 else r[j + 1]
                    delta = (d(a, c) + d(b, d2)) - (d(a, b) + d(c, d2))
                    if delta < best_delta - 1e-12:
                        best_delta = delta
                        best_i = i
                        best_j = j
            if best_i != -1:
                r = r[:best_i] + r[best_i:best_j + 1][::-1] + r[best_j + 1:]
                improved = True
        return r

    def try_relocate_between():
        nonlocal routes
        improved = False
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            ri = routes[i]
            for pos in range(len(ri)):
                c = ri[pos]
                dc = demand_of(c)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if loads[j] + dc > cap:
                        continue
                    best_pos = None
                    best_delta = 0.0
                    for ins in range(len(rj) + 1):
                        a = depot if ins == 0 else rj[ins - 1]
                        b = depot if ins == len(rj) else rj[ins]
                        delta_ins = d(a, c) + d(c, b) - d(a, b)
                        if delta_ins < best_delta - 1e-12:
                            best_delta = delta_ins
                            best_pos = ins
                    a = depot if pos == 0 else ri[pos - 1]
                    b = depot if pos == len(ri) - 1 else ri[pos + 1]
                    delta_rem = d(a, b) - d(a, c) - d(c, b)
                    if best_pos is not None and delta_rem + best_delta < -1e-12:
                        routes[i] = ri[:pos] + ri[pos + 1:]
                        routes[j] = rj[:best_pos] + [c] + rj[best_pos:]
                        improved = True
                        return True
        return improved

    def try_swap_between():
        nonlocal routes
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                for pi in range(len(ri)):
                    a1 = depot if pi == 0 else ri[pi - 1]
                    x = ri[pi]
                    b1 = depot if pi == len(ri) - 1 else ri[pi + 1]
                    dx = demand_of(x)
                    for pj in range(len(rj)):
                        a2 = depot if pj == 0 else rj[pj - 1]
                        y = rj[pj]
                        b2 = depot if pj == len(rj) - 1 else rj[pj + 1]
                        dy = demand_of(y)
                        if loads[i] - dx + dy > cap or loads[j] - dy + dx > cap:
                            continue
                        delta = (d(a1, y) + d(y, b1) - d(a1, x) - d(x, b1)) + (d(a2, x) + d(x, b2) - d(a2, y) - d(y, b2))
                        if delta < -1e-12:
                            ri2 = ri[:]
                            rj2 = rj[:]
                            ri2[pi] = y
                            rj2[pj] = x
                            routes[i] = ri2
                            routes[j] = rj2
                            return True
        return False

    def try_merge_routes():
        nonlocal routes
        best = None
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                if route_load(ri) + route_load(rj) > cap:
                    continue
                candidates = [
                    (ri + rj, route_cost(ri) + route_cost(rj) - route_cost(ri + rj)),
                    (ri + rj[::-1], route_cost(ri) + route_cost(rj) - route_cost(ri + rj[::-1])),
                    (ri[::-1] + rj, route_cost(ri) + route_cost(rj) - route_cost(ri[::-1] + rj)),
                    (ri[::-1] + rj[::-1], route_cost(ri) + route_cost(rj) - route_cost(ri[::-1] + rj[::-1])),
                ]
                for merged, gain in candidates:
                    if gain > 1e-12 and (best is None or gain > best[0] or (abs(gain - best[0]) <= 1e-12 and (i, j) < (best[1], best[2]))):
                        best = (gain, i, j, merged)
        if best is not None:
            _, i, j, merged = best
            new_routes = []
            for idx, r in enumerate(routes):
                if idx != i and idx != j:
                    new_routes.append(r)
            new_routes.append(merged)
            routes = new_routes
            return True
        return False

    def optimize_routes():
        nonlocal routes
        for idx in range(len(routes)):
            routes[idx] = two_opt_route(routes[idx])

    optimize_routes()
    changed = True
    rounds = 0
    while changed and rounds < 50:
        changed = False
        rounds += 1
        if try_merge_routes():
            optimize_routes()
            changed = True
            continue
        if try_relocate_between():
            optimize_routes()
            changed = True
            continue
        if try_swap_between():
            optimize_routes()
            changed = True
            continue

    routes = [r for r in routes if r]
    return routes
